-- Service Info Tables (Settings)
CREATE TABLE salaryslipinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE bankstatementinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE academictranscriptinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE criminalrecordinfo_serv (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE celibacyinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE contractinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE courtjudgmentinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE notarialactinfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');
CREATE TABLE poainfo (id INT AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(255), description TEXT, requirements TEXT, processing_time VARCHAR(100), price INT, currency VARCHAR(10), provided_by VARCHAR(255), status ENUM('Active', 'Inactive') DEFAULT 'Active');

