-- Application Tables
CREATE TABLE applicationsalaryslip (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(255), email VARCHAR(255), phone VARCHAR(20), national_id VARCHAR(20), employer_name VARCHAR(255), monthly_net INT, document_path VARCHAR(512), service_name VARCHAR(255), status ENUM('Pending', 'Approved', 'Rejected') DEFAULT 'Pending', ai_forgery_score FLOAT, ai_verdict VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applicationbankstatement (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(255), email VARCHAR(255), phone VARCHAR(20), national_id VARCHAR(20), bank_name VARCHAR(255), account_number VARCHAR(50), document_path VARCHAR(512), service_name VARCHAR(255), status ENUM('Pending', 'Approved', 'Rejected') DEFAULT 'Pending', ai_forgery_score FLOAT, ai_verdict VARCHAR(50), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
